// Guard + flatten + classify the incoming message for routing.
//
// body: { org_prompt, message: { direction, body, media_type, media_base64,
//         media_mime, sent_at }, contact, detect_*, thread[] }
const SECRET = '__N8N_WEBHOOK_SECRET__';

const item = $input.first().json;
if ((item.headers ?? {})['x-sanayed-secret'] !== SECRET) {
  throw new Error('unauthorized');
}

const body = item.body ?? item;
const msg = body.message ?? {};
const mime = String(msg.media_mime ?? '');
const hasMedia = Boolean(msg.media_base64);

let kind = 'text';
if (hasMedia && mime.startsWith('image/')) kind = 'image';
else if (hasMedia && mime.startsWith('audio/')) kind = 'audio';

return [{
  json: {
    kind,
    org_prompt: body.org_prompt ?? null,
    contact: body.contact ?? {},
    detect_unauthorized_promise: body.detect_unauthorized_promise,
    detect_off_channel: body.detect_off_channel,
    message: { direction: msg.direction, body: msg.body, media_type: msg.media_type, sent_at: msg.sent_at },
    thread: Array.isArray(body.thread) ? body.thread : [],
    media_base64: hasMedia ? String(msg.media_base64) : '',
    media_mime: mime,
  },
}];

// Assemble the judge request. Reached three ways:
//   text  -> straight from Prepare
//   image -> straight from Prepare (the judge model sees the image itself)
//   audio -> via Whisper, $json.text is the transcription
const prep = $('Prepare').first().json;
const cur = $input.first().json;

const kind = prep.kind;
const transcript = kind === 'audio' ? String(cur.text ?? '').trim() : '';

const agent = prep.contact?.agent_name || 'the agent';
const client = prep.contact?.display_name || 'the client';

const lines = (prep.thread ?? []).map((m) => {
  const who = m.direction === 'in' ? 'Client' : 'Agent';
  const text = m.transcript || m.body || ('[' + (m.media_type || 'message') + ']');
  return who + ': ' + text;
});

const orgPrompt = prep.org_prompt ||
  'You review WhatsApp conversations between staff and clients. Alert the manager when a staff member promises something the company may not honour, moves the client off the official channel, or when the client is angry, threatening to leave, or asking for a manager.';

const disabled = [];
if (prep.detect_unauthorized_promise === false) disabled.push('unauthorized_promise');
if (prep.detect_off_channel === false) disabled.push('off_channel');

const system = orgPrompt + `

---
OUTPUT CONTRACT (mandatory, overrides anything above about formatting)

You are judging whether the SALES MANAGER must personally intervene in this conversation. Most messages need nothing: when in doubt, do not alert — a false alarm costs more than a miss, because a noisy feed stops being read.

Do NOT alert for slow replies or silence; those are measured precisely elsewhere.${disabled.length ? '\nNEVER use these types (disabled by the manager): ' + disabled.join(', ') + '.' : ''}

Write "title" and "insight" in the same language the conversation is in. Name the people: the agent is "${agent}", the client is "${client}"${prep.contact?.is_vip ? ' (VIP client)' : ''}.

RESPOND ONLY WITH JSON:
{
  "needs_attention": false,
  "type": "unauthorized_promise" | "off_channel" | "escalation" | "other",
  "severity": "urgent" | "high" | "medium" | "low",
  "title": "short headline naming who did what",
  "insight": "one or two sentences the manager can act on",
  "recommended_action": "the single next step",
  "evidence": { "quote": "the exact words that triggered this, copied verbatim" },
  "media_description": ""
}
${kind === 'image' ? '\n"media_description" is REQUIRED here: one factual sentence describing what the attached image shows (including any visible text), in the conversation language — even when needs_attention is false.' : 'Leave "media_description" empty.'}

If nothing requires the manager, return needs_attention: false, leave the other fields empty${kind === 'image' ? ' except media_description' : ''}.`;

const newestWho = prep.message?.direction === 'in' ? 'Client' : 'Agent';
let newest;
if (kind === 'audio') {
  newest = newestWho + ' (voice note, transcribed): ' + (transcript || '[unintelligible]');
} else if (kind === 'image') {
  newest = newestWho + ' sent the attached image' + (prep.message?.body ? ' with caption: ' + prep.message.body : '') + '.';
} else {
  newest = newestWho + ': ' + (prep.message?.body || '[' + (prep.message?.media_type || 'message') + ']');
}

const userText = 'Conversation (oldest first):\n' + lines.join('\n').slice(-6000) +
  '\n\nNewest message (the one to judge, in context): ' + newest;

const userContent = kind === 'image'
  ? [
      { type: 'text', text: userText },
      { type: 'image_url', image_url: { url: 'data:' + prep.media_mime + ';base64,' + prep.media_base64 } },
    ]
  : userText;

return [{
  json: {
    kind,
    transcript,
    messages: [
      { role: 'system', content: system },
      { role: 'user', content: userContent },
    ],
  },
}];

// Parse + clamp the verdict, and attach the media transcript/description the
// app stores on the message row.
const built = $('Build messages').first().json;
const raw = $input.first().json;
const content = raw?.choices?.[0]?.message?.content ?? '';

let parsed;
try {
  parsed = JSON.parse(content);
} catch (e) {
  const start = content.indexOf('{');
  const end = content.lastIndexOf('}');
  if (start === -1 || end <= start) {
    return [{ json: { needs_attention: false, transcript: built.transcript || '' } }];
  }
  parsed = JSON.parse(content.slice(start, end + 1));
}

const TYPES = ['unauthorized_promise', 'off_channel', 'escalation', 'other'];
const SEVERITIES = ['urgent', 'high', 'medium', 'low'];

// audio -> the Whisper transcription; image -> the judge's description.
const transcript = built.kind === 'audio'
  ? (built.transcript || '')
  : String(parsed.media_description ?? '').slice(0, 2000);

return [{
  json: {
    needs_attention: parsed.needs_attention === true,
    type: TYPES.includes(parsed.type) ? parsed.type : 'other',
    severity: SEVERITIES.includes(parsed.severity) ? parsed.severity : 'medium',
    title: String(parsed.title ?? '').slice(0, 300),
    insight: String(parsed.insight ?? '').slice(0, 2000),
    recommended_action: String(parsed.recommended_action ?? '').slice(0, 1000),
    evidence: typeof parsed.evidence === 'object' && parsed.evidence !== null ? parsed.evidence : {},
    transcript,
  },
}];
